-- Post-condition, asserted in the same transaction: every definer function in
-- ff_private is owned by ff_migration_owner, and none of them is owned by the
-- deploying role. If any statement above silently missed a function, this
-- aborts the whole migration rather than leaving a split ownership state.
do $$
declare n_wrong int;
begin
  select count(*) into n_wrong
  from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
  where ns.nspname in ('public','ff_private') and p.prosecdef
    and pg_get_userbyid(p.proowner) <> 'ff_migration_owner';
  if n_wrong > 0 then
    raise exception 'ownership transfer incomplete: % SECURITY DEFINER function(s) not owned by ff_migration_owner', n_wrong
      using errcode = '42501';
  end if;
end $$;
